# -*- coding: utf-8 -*-
from pathlib import Path
import json
from lesson_authoring import entry as E
BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_spec'
B=[['拉丁 domare → domitare','驯服、制服；domitare 是反复或强化动作的形式']]
D=B+[['古法语 donter / danter → 中古英语 daunten','制服、使屈服'],['现代英语 daunt','使胆怯，削弱做事的信心']]
W=[E('daunt','英美 /dɔːnt/','使胆怯；使退缩','困难一摆到面前，勇气就被压下去一些。','拉丁 domitare“制服、驯服”经古法语 danter 进入中古英语 daunten。过去制服对象，后来可以说压低一个人的勇气。',D,'The task daunts me. 是任务让我有点发怵，不是任务本身会感到害怕。常见的被动说法是 be daunted by something“被某事吓住、觉得难以应对”。','daunt someone；be daunted by；fail to daunt someone；nothing daunted。','frighten 可指突如其来的恐惧；daunt 常是面对难度、规模或对手，觉得信心受挫。',('The amount of paperwork did not daunt her.','大量文书工作没有把她吓退。'),('The steep climb would daunt many inexperienced hikers.','这段陡峭的攀登会让许多缺乏经验的徒步者望而却步。'),sources=['https://www.etymonline.com/word/daunt','https://www.oxfordlearnersdictionaries.com/definition/english/daunt']),
E('daunting','英美 /ˈdɔːntɪŋ/','令人畏缩的；让人发怵的','还没开始，就觉得这件事真难、真大，不好应付。','daunt + -ing，形成说明事物给人什么感受的形容词。不是说任务自己害怕，而是任务让人害怕。',D+[['英语 daunt + -ing → daunting','会削弱信心、使人畏缩的']],'a daunting task 是看起来很难应对的任务。常用来承认挑战很大，但并没有断言不可能完成；拆成小步骤后，任务可能就没那么 daunting。','a daunting task；a daunting challenge；a daunting prospect；seem daunting。','daunting 描写带来压力的事，daunted 描写感到压力的人。The task is daunting；I feel daunted。',('Writing the first chapter seemed daunting until I made an outline.','写第一章本来让我发怵，直到我列出了提纲。'),('Moving to a new country can be a daunting prospect.','搬到一个新国家生活，想起来可能会让人畏难。'),sources=['https://en.wiktionary.org/wiki/daunting','https://www.oxfordlearnersdictionaries.com/definition/english/daunting']),
E('daunted','英美 /ˈdɔːntɪd/','感到畏难的；被吓住的','看到难度后，自己的信心缩了一下。','daunt + -ed，既是过去分词，也可描述受影响后的心理状态。因为词干末尾是 /t/，-ed 多出一个 /ɪd/ 音节。',D+[['英语 daunt + -ed → daunted','被困难压低了勇气；感到畏缩']],'feel daunted by the scale of a project 是被项目的规模震住，觉得难以应付。它不等于已经放弃，感到 daunted 的人仍然可能继续做。','feel daunted；be daunted by；a little daunted；not easily daunted。','daunting 是“令人发怵的”，daunted 是“自己发怵的”。和 interested / interesting 一样，要看谁受到影响。',('I felt daunted by the number of unfamiliar terms.','看到这么多陌生术语，我有些发怵。'),('She looked daunted at first, but soon began asking practical questions.','她起初显得有些畏难，但很快开始提出实际问题。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/daunt','https://en.wiktionary.org/wiki/daunted']),
E('undaunted','英美 /ˌʌnˈdɔːntɪd/','不气馁的；未被吓退的','困难确实在，但它没有让自己停下来。','un-（不）+ daunted。中古英语已使用，早期可说马未被驯服，后来常说人没有被恐惧或困难压倒。',D[:2]+[['中古英语 un- + daunted → undaunted','未驯服的；未被制服的'],['现代英语 undaunted','面对困难仍有勇气、仍然坚持']],'remain undaunted 强调遭遇挫折后仍不退缩。它不表示完全不知道危险，也不保证结果一定成功，只是在描述面对问题的态度。','remain undaunted；undaunted by setbacks；seem undaunted；continue undaunted。','dauntless 较像赞美勇敢的性格；undaunted 更容易接具体挫折，强调“这件事仍没吓退他”。',('Undaunted by the rejection, he revised the proposal and tried again.','他没有因被拒绝而气馁，修改方案后又试了一次。'),('The team remained undaunted despite losing its main sponsor.','尽管失去了主要赞助方，团队仍然没有退缩。'),sources=['https://www.etymonline.com/word/undaunted','https://www.oxfordlearnersdictionaries.com/definition/english/undaunted']),
E('dauntless','英美 /ˈdɔːntləs/','无畏的；不屈不挠的','面对困难时，仍有一股不容易被压倒的勇气。','daunt + -less，“没有畏缩”的形容词。-less 否定的是退缩状态，不是说缺乏能力。',D+[['英语 daunt + -less → dauntless','不容易被困难吓退的']],'a dauntless explorer 带有文学、赞颂色彩，比普通 brave 更郑重。可以形容勇气或精神，不必涉及战争和肉体危险。','a dauntless spirit；dauntless courage；a dauntless campaigner；remain dauntless。','fearless 强调不害怕；dauntless 尤其突出不被阻力打退。它不等于 reckless“鲁莽的”。',('The biography celebrates her dauntless pursuit of an education.','这本传记赞扬了她求学时不屈不挠的精神。'),('The dauntless crew continued the rescue in worsening weather.','天气不断恶化，这支无畏的队伍仍继续救援。'),sources=['https://en.wiktionary.org/wiki/dauntless','https://www.oxfordlearnersdictionaries.com/definition/english/dauntless']),
E('indomitable','英 /ɪnˈdɒmɪtəbəl/；美 /ɪnˈdɑːmɪtəbəl/','不屈不挠的；难以征服的','再大的压力也很难把那股意志压服。','后期拉丁 indomitabilis 借入，in- 表不，domit- 接 domitare“驯服”，-abilis 对应能够被……的。现代可认出 in- + domitable，但历史不是从英语 daunt 拼出这个长词。',B+[['后期拉丁 indomitabilis → 英语 indomitable','不能被驯服、制服的'],['描写人的常用义','意志不屈、不接受失败的']],'an indomitable spirit 是不屈的精神，常用于赞扬面对长期困难仍坚持的人。不要只译成“强壮”，因为它主要可以说意志，而非肌肉力量。','an indomitable spirit；indomitable courage；an indomitable will；an indomitable campaigner。','daunting 是让别人退缩的；indomitable 是自己难以被压服的。两者可以在同一个场景里相对：a daunting challenge, an indomitable spirit。',('Her indomitable spirit kept the small school alive through years of difficulty.','她不屈的精神使这所小学校熬过了多年的困难。'),('The novel portrays a quiet woman with an indomitable will.','小说描写了一位性情安静却意志不屈的女性。'),sources=['https://www.etymonline.com/word/indomitable','https://www.oxfordlearnersdictionaries.com/definition/english/indomitable'])]
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());r=next(x for x in m['roots']if x['id']=='C0339');c=next(x for x in json.loads((BASE/'.cache/catalog.json').read_text())if x['id']=='C0339');keep={w['word']for w in W};excluded={w:'按用户要求暂略：低频肯定形式，保留常用 indomitable 及 daunt 词族。'for w in(set(r['family'])|set(c['family'])|set(c.get('unmatched',[])))-keep}
ROOT=[dict(id='C0339',meaning='驯服；使屈服',core='domit- 原来是“制服、驯服”，后来常用来谈人的勇气是否被压倒。',image='困难向人压来：daunting 是它造成的压力，daunted 是人的畏难，undaunted 是没有退缩。',intro='daunt 经法语变了形，看起来和 indomitable 差很多，却都能接回拉丁 domitare。先把“制服”放到勇气上，就能串起这一组。',forms='拉丁 domare → domitare；经古法语 danter 得到 daunt。indomitable 则另从后期拉丁 indomitabilis 借入，保留明显的 domit-。',branches=[['让人畏难与感到畏难','daunt、daunting、daunted'],['没有被压倒','undaunted、dauntless、indomitable']],contrasts='daunting 描写让人发怵的对象；daunted 描写受到影响的人。indomitable 的 in- 是否定，不是“向里面”。',practice='用 The task was daunting, but she remained undaunted. 串起挑战与人的反应。',words=[w for w in r['family']if w in keep],exclude=excluded,sources=['https://www.etymonline.com/word/daunt','https://www.etymonline.com/word/indomitable'])]
assert all(w['word']in m['owned_words']for w in W)
assert not(set(c['family'])|set(c.get('unmatched',[])))-set(ROOT[0]['words'])-set(excluded)
for w in W:assert len(w['examples'])>=2 and all(len(n)==2 and all(isinstance(x,str)and x for x in n)for n in w['history'])
for k,d in [('roots',ROOT),('words',W)]: (OUT/f'{k}_batch200_spec_197_domit.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print('C0339',len(W),'new',len(ROOT[0]['words']),'retained')
